CREATE OR REPLACE FUNCTION public.trg_update_region()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.region := (
        SELECT cr.libelle 
        FROM combinaison_region cr
        WHERE 
            cr.region1 = trouver_region(NEW.num1) AND
            cr.region2 = trouver_region(NEW.num2)
    );

    IF NEW.region IS NULL THEN
        NEW.region := 'INCONNU';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.determiner_univers_et_forme(num1_id integer, num2_id integer, OUT result_univers_id integer, OUT result_forme_id integer, OUT result_forme_composee character varying)
 RETURNS record
 LANGUAGE plpgsql
AS $function$
DECLARE
    room_num1 INT; room_num2 INT;
    ash_num1 INT; ash_num2 INT;
    lot_num1 INT; lot_num2 INT;
    col_num1 INT; col_num2 INT;
    forme1 INT; forme2 INT;
BEGIN
    -- Récupérer les informations des numéros
    SELECT rn.numero, c.cell_id AS room_id, r.ash_id, r.lot_id 
    INTO col_num1, room_num1, ash_num1, lot_num1
    FROM room_numbers rn 
    JOIN cells c ON rn.numero = c.value 
    JOIN rooms r ON c.cell_id = r.room_id
    WHERE rn.numero = num1_id;

    SELECT rn.numero, c.cell_id AS room_id, r.ash_id, r.lot_id 
    INTO col_num2, room_num2, ash_num2, lot_num2
    FROM room_numbers rn 
    JOIN cells c ON rn.numero = c.value 
    JOIN rooms r ON c.cell_id = r.room_id
    WHERE rn.numero = num2_id;

    -- Déterminer l'univers et la forme selon les règles
    -- Mundo et Fruity
    IF (ash_num1 = ash_num2) THEN
        IF (ash_num1 = 1 AND room_num1 IN (9,13) AND room_num2 IN (9,13)) OR
           (ash_num1 = 2 AND room_num1 IN (10,14) AND room_num2 IN (10,14)) OR
           (ash_num1 = 3 AND room_num1 IN (11,15) AND room_num2 IN (11,15)) OR
           (ash_num1 = 4 AND room_num1 IN (12,16) AND room_num2 IN (12,16)) THEN
            result_univers_id := 2; -- fruity
        ELSE
            result_univers_id := 1; -- mundo
        END IF;

        -- Forme selon ash
        SELECT forme_id INTO forme1 FROM formes WHERE forme_name = (SELECT ash_name FROM ashs WHERE ash_id = ash_num1);
        result_forme_id := forme1;
        result_forme_composee := NULL;

    ELSIF (lot_num1 = lot_num2) THEN
        IF (lot_num1 = 1 AND room_num1 IN (1,2,3,4) AND room_num2 IN (1,2,3,4)) OR
           (lot_num1 = 2 AND room_num1 IN (5,6,7,8) AND room_num2 IN (5,6,7,8)) OR
           (lot_num1 = 3 AND room_num1 IN (9,10,11,12) AND room_num2 IN (9,10,11,12)) OR
           (lot_num1 = 4 AND room_num1 IN (13,14,15,16) AND room_num2 IN (13,14,15,16)) THEN
            -- Cas déjà couverts par mundo
            NULL;
        ELSE
            result_univers_id := 2; -- fruity
            -- Forme selon lot
            SELECT forme_id INTO forme1 FROM formes WHERE forme_name = (SELECT lot_name FROM lots WHERE id = lot_num1);
            result_forme_id := forme1;
            result_forme_composee := NULL;
        END IF;

    -- Trigga
    ELSIF (col_num1 IN (3,4,5,6) AND col_num2 IN (3,4,5,6)) THEN
        result_univers_id := 3; -- trigga

        -- Déterminer la forme composée
        IF ash_num1 = 1 AND ash_num2 = 1 THEN -- ash16
            result_forme_composee := 'carre';
            result_forme_id := (SELECT forme_id FROM formes WHERE forme_name = 'carre');
        ELSIF lot_num1 = 1 AND lot_num2 = 1 THEN
            result_forme_composee := 'carre';
            result_forme_id := (SELECT forme_id FROM formes WHERE forme_name = 'carre');
        ELSE
            -- Forme du premier numéro (room la plus petite)
            IF room_num1 < room_num2 THEN
                SELECT a.ash_id INTO forme1 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num1;
                SELECT a.ash_id INTO forme2 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num2;
            ELSE
                SELECT a.ash_id INTO forme1 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num2;
                SELECT a.ash_id INTO forme2 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num1;
            END IF;

            IF forme1 = forme2 THEN
                result_forme_composee := (SELECT forme_name FROM formes WHERE forme_id = forme1);
                result_forme_id := forme1;
            ELSE
                result_forme_composee := (SELECT forme_name FROM formes WHERE forme_id = forme1) || '-' || (SELECT forme_name FROM formes WHERE forme_id = forme2);
                result_forme_id := NULL; -- ou garder forme1 comme forme principale
            END IF;
        END IF;

    -- Sunshine
    ELSIF ((col_num1 IN (1,2) AND col_num2 IN (3,4,5,6)) OR (col_num1 IN (3,4,5,6) AND col_num2 IN (1,2))) THEN
        result_univers_id := 4; -- sunshine

        -- Déterminer la forme composée
        SELECT a.ash_id INTO forme1 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num1;
        SELECT a.ash_id INTO forme2 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num2;

        IF forme1 = forme2 THEN
            result_forme_composee := (SELECT forme_name FROM formes WHERE forme_id = forme1);
            result_forme_id := forme1;
        ELSE
            result_forme_composee := (SELECT forme_name FROM formes WHERE forme_id = forme1) || '-' || (SELECT forme_name FROM formes WHERE forme_id = forme2);
            result_forme_id := NULL; -- ou garder forme1 comme forme principale
        END IF;

    -- Roaster
    ELSIF (col_num1 IN (1,2) AND col_num2 IN (1,2) AND 
           ash_num1 != ash_num2 AND lot_num1 != lot_num2 AND
           EXISTS (SELECT 1 FROM associationsroaster WHERE room1_id = room_num1 AND room2_id = room_num2)) THEN
        result_univers_id := 5; -- roaster

        -- Déterminer la forme composée
        IF room_num1 < room_num2 THEN
            SELECT a.ash_id INTO forme1 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num1;
            SELECT a.ash_id INTO forme2 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num2;
        ELSE
            SELECT a.ash_id INTO forme1 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num2;
            SELECT a.ash_id INTO forme2 FROM ashs a JOIN rooms r ON a.ash_id = r.ash_id WHERE r.id = room_num1;
        END IF;

        IF forme1 = forme2 THEN
            result_forme_composee := (SELECT forme_name FROM formes WHERE forme_id = forme1);
            result_forme_id := forme1;
        ELSE
            result_forme_composee := (SELECT forme_name FROM formes WHERE forme_id = forme1) || '-' || (SELECT forme_name FROM formes WHERE forme_id = forme2);
            result_forme_id := NULL; -- ou garder forme1 comme forme principale
        END IF;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.trouver_region(num integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    r VARCHAR(1);
BEGIN
    SELECT region INTO r FROM region 
    WHERE num = ANY(numeros)
    LIMIT 1;

    IF r IS NULL THEN
        RAISE NOTICE 'Numéro % non trouvé dans aucune région', num;
    END IF;

    RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_update_gentillee()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.position_num1 IS NOT NULL AND NEW.position_num2 IS NOT NULL THEN
        NEW.gentillee := NEW.position_num1 || NEW.position_num2;
    ELSE
        NEW.gentillee := NULL;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_update_chip()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.ligne IS NOT NULL AND NEW.colonne IS NOT NULL THEN
        NEW.chip := 'chip' || (
            (CAST(SUBSTRING(NEW.ligne, 2) AS INTEGER) - 1) * 6 + 
            CAST(SUBSTRING(NEW.colonne, 2) AS INTEGER
        ));
    ELSE
        NEW.chip := NULL;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.determiner_beastie(num1 integer, num2 integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_groupe1 TEXT;
    v_groupe2 TEXT;
    v_beastie_name TEXT;
    v_temp TEXT;
BEGIN
    -- Déterminer les groupes pour num1 et num2
    SELECT groupe_name INTO v_groupe1 FROM groupes WHERE value = num1;
    SELECT groupe_name INTO v_groupe2 FROM groupes WHERE value = num2;

    -- Assurer que v_groupe1 est toujours le plus petit pour la bidirectionnalité
    IF v_groupe1 > v_groupe2 THEN
        v_temp := v_groupe1;
        v_groupe1 := v_groupe2;
        v_groupe2 := v_temp;
    END IF;

    -- Déterminer la beastie en fonction des groupes
    SELECT b.beastie_name INTO v_beastie_name
    FROM group_combinations gc
    JOIN beasties b ON gc.beastie_id = b.beastie_id
    WHERE gc.groupe1 = v_groupe1 AND gc.groupe2 = v_groupe2;

    RETURN v_beastie_name;
END;
$function$

CREATE OR REPLACE FUNCTION public.determiner_univers_mundo_fruity(ash_num1 integer, ash_num2 integer, room_num1 integer, room_num2 integer, lot_num1 integer, lot_num2 integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    forme1_id INT;
    forme1_name TEXT;
    forme2_id INT;
    forme2_name TEXT;
    forme_id TEXT;
    forme_composee TEXT;
    univers TEXT;
BEGIN
    -- Déterminer l'univers et la forme selon les règles
    -- Mundo et Fruity
    IF (ash_num1 = ash_num2) THEN
        -- Déterminer la forme associée à ash_num1
        SELECT forme_associee_id INTO forme1_id FROM Ash WHERE id = ash_num1;
        SELECT forme_name INTO forme1_name FROM formes WHERE forme_id = forme1_id;

        -- Vérifier les conditions spécifiques pour fruity
        IF (ash_num1 = 16 AND room_num1 IN (9,13) AND room_num2 IN (9,13)) OR
           (ash_num1 = 20 AND room_num1 IN (10,14) AND room_num2 IN (10,14)) OR
           (ash_num1 = 24 AND room_num1 IN (11,15) AND room_num2 IN (11,15)) OR
           (ash_num1 = 30 AND room_num1 IN (12,16) AND room_num2 IN (12,16)) THEN
            univers := 'fruity';
        ELSE
            univers := 'mundo';
        END IF;

        -- Forme selon ash
        forme_id := forme1_name;
        forme_composee := NULL;

    ELSIF (lot_num1 = lot_num2) THEN
        -- Déterminer la forme associée à lot_num1
        CASE lot_num1
            WHEN 1 THEN forme1_id := 1;
            WHEN 2 THEN forme1_id := 2;
            WHEN 3 THEN forme1_id := 3;
            WHEN 4 THEN forme1_id := 4;
            ELSE forme1_id := NULL;
        END CASE;

        SELECT forme_name INTO forme1_name FROM formes WHERE forme_id = forme1_id;

        -- Vérifier les conditions spécifiques pour fruity
        IF (lot_num1 = 1 AND room_num1 IN (1,2,3,4) AND room_num2 IN (1,2,3,4)) OR
           (lot_num1 = 2 AND room_num1 IN (5,6,7,8) AND room_num2 IN (5,6,7,8)) OR
           (lot_num1 = 3 AND room_num1 IN (9,10,11,12) AND room_num2 IN (9,10,11,12)) OR
           (lot_num1 = 4 AND room_num1 IN (13,14,15,16) AND room_num2 IN (13,14,15,16)) THEN
            -- Cas déjà couverts par mundo
            NULL;
        ELSE
            univers := 'fruity';
        END IF;

        -- Forme selon lot
        forme_id := forme1_name;
    END IF;

    RETURN univers;
END;
$function$

CREATE OR REPLACE FUNCTION public.determiner_univers_sunshine(num1 integer, num2 integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    col_num1 TEXT;
    col_num2 TEXT;
BEGIN
    -- Vérifier si num1 appartient à col1_col2 et num2 appartient à col3_col4_col5_col6 ou l'inverse
    SELECT 'col1_col2' INTO col_num1
    FROM col1_col2
    WHERE numero = num1;

    SELECT 'col3_col4_col5_col6' INTO col_num2
    FROM col3_col4_col5_col6
    WHERE numero = num2;

    IF (col_num1 IS NOT NULL AND col_num2 IS NOT NULL) THEN
        RETURN 'sunshine';
    END IF;

    -- Vérifier l'inverse
    SELECT 'col1_col2' INTO col_num2
    FROM col1_col2
    WHERE numero = num2;

    SELECT 'col3_col4_col5_col6' INTO col_num1
    FROM col3_col4_col5_col6
    WHERE numero = num1;

    IF (col_num1 IS NOT NULL AND col_num2 IS NOT NULL) THEN
        RETURN 'sunshine';
    END IF;

    RETURN NULL; -- Si les conditions ne sont pas remplies, retourne NULL
END;
$function$

