CREATE OR REPLACE FUNCTION public.determiner_forme_composee(ash_num1 character varying, ash_num2 character varying, room_num1 character varying, room_num2 character varying)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    forme1 TEXT;
    forme2 TEXT;
    forme_composee TEXT;
    room_id_num1 INT;
    room_id_num2 INT;
BEGIN
    -- Extraire les chiffres des valeurs de room_num1 et room_num2
    room_id_num1 := REGEXP_REPLACE(room_num1, '[^0-9]+', '', 'g')::INT;
    room_id_num2 := REGEXP_REPLACE(room_num2, '[^0-9]+', '', 'g')::INT;

    -- Déterminer la forme associée à ash_num1
    CASE ash_num1
        WHEN 'ash16' THEN forme1 := 'carre';
        WHEN 'ash20' THEN forme1 := 'triangle';
        WHEN 'ash24' THEN forme1 := 'cercle';
        WHEN 'ash30' THEN forme1 := 'rectangle';
        ELSE forme1 := NULL;
    END CASE;

    -- Déterminer la forme associée à ash_num2
    CASE ash_num2
        WHEN 'ash16' THEN forme2 := 'carre';
        WHEN 'ash20' THEN forme2 := 'triangle';
        WHEN 'ash24' THEN forme2 := 'cercle';
        WHEN 'ash30' THEN forme2 := 'rectangle';
        ELSE forme2 := NULL;
    END CASE;

    -- Vérifier si les formes sont valides
    IF forme1 IS NOT NULL AND forme2 IS NOT NULL THEN
        -- Vérifier l'ordre des rooms pour déterminer la forme composée
        IF room_id_num1 < room_id_num2 THEN
            forme_composee := forme1 || '-' || forme2;
        ELSE
            forme_composee := forme2 || '-' || forme1;
        END IF;
    ELSE
        forme_composee := NULL;
    END IF;

    RETURN forme_composee;
END;
$function$

CREATE OR REPLACE FUNCTION public.determiner_forme_composee(ash_num1 character varying, ash_num2 character varying, room_num1 character varying, room_num2 character varying, lot_num1 character varying, lot_num2 character varying)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    forme1 TEXT;
    forme2 TEXT;
    forme_composee TEXT;
    room_id_num1 INT;
    room_id_num2 INT;
    lot_id_num1 INT;
    lot_id_num2 INT;
BEGIN
    -- Extraire les chiffres des valeurs de room_num1 et room_num2
    room_id_num1 := REGEXP_REPLACE(room_num1, '[^0-9]+', '', 'g')::INT;
    room_id_num2 := REGEXP_REPLACE(room_num2, '[^0-9]+', '', 'g')::INT;

    -- Extraire les chiffres des valeurs de lot_num1 et lot_num2
    lot_id_num1 := REGEXP_REPLACE(lot_num1, '[^0-9]+', '', 'g')::INT;
    lot_id_num2 := REGEXP_REPLACE(lot_num2, '[^0-9]+', '', 'g')::INT;

    -- Vérifier si lot_num1 et lot_num2 sont différents
    IF lot_id_num1 != lot_id_num2 THEN
        -- Déterminer la forme associée à ash_num1
        CASE ash_num1
            WHEN 'ash16' THEN forme1 := 'carre';
            WHEN 'ash20' THEN forme1 := 'triangle';
            WHEN 'ash24' THEN forme1 := 'cercle';
            WHEN 'ash30' THEN forme1 := 'rectangle';
            ELSE forme1 := NULL;
        END CASE;

        -- Déterminer la forme associée à ash_num2
        CASE ash_num2
            WHEN 'ash16' THEN forme2 := 'carre';
            WHEN 'ash20' THEN forme2 := 'triangle';
            WHEN 'ash24' THEN forme2 := 'cercle';
            WHEN 'ash30' THEN forme2 := 'rectangle';
            ELSE forme2 := NULL;
        END CASE;

        -- Vérifier si les formes sont valides
        IF forme1 IS NOT NULL AND forme2 IS NOT NULL THEN
            -- Vérifier l'ordre des rooms pour déterminer la forme composée
            IF room_id_num1 < room_id_num2 THEN
                forme_composee := forme1 || '-' || forme2;
            ELSE
                forme_composee := forme2 || '-' || forme1;
            END IF;
        ELSE
            forme_composee := NULL;
        END IF;
    ELSE
        -- Si lot_num1 = lot_num2, utiliser la forme associée au lot
        CASE lot_id_num1
            WHEN 1 THEN forme_composee := 'carre';
            WHEN 2 THEN forme_composee := 'triangle';
            WHEN 3 THEN forme_composee := 'cercle';
            WHEN 4 THEN forme_composee := 'rectangle';
            ELSE forme_composee := NULL;
        END CASE;
    END IF;

    RETURN forme_composee;
END;
$function$

CREATE OR REPLACE FUNCTION public.determiner_univers_mundo_fruity(ash_num1 character varying, ash_num2 character varying, room_num1 character varying, room_num2 character varying, lot_num1 character varying, lot_num2 character varying)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    forme1_id INT;
    forme1_name TEXT;
    forme2_id INT;
    forme2_name TEXT;
    v_forme_id TEXT; -- Alias pour éviter l'ambiguïté
    forme_composee TEXT;
    univers TEXT;
    ash_num1_int INT;
    ash_num2_int INT;
    room_num1_int INT;
    room_num2_int INT;
    lot_num1_int INT;
    lot_num2_int INT;
BEGIN
    -- Extraire les chiffres et convertir en INT
    ash_num1_int := REGEXP_REPLACE(ash_num1, '[^0-9]+', '', 'g')::INT;
    ash_num2_int := REGEXP_REPLACE(ash_num2, '[^0-9]+', '', 'g')::INT;
    room_num1_int := REGEXP_REPLACE(room_num1, '[^0-9]+', '', 'g')::INT;
    room_num2_int := REGEXP_REPLACE(room_num2, '[^0-9]+', '', 'g')::INT;
    lot_num1_int := REGEXP_REPLACE(lot_num1, '[^0-9]+', '', 'g')::INT;
    lot_num2_int := REGEXP_REPLACE(lot_num2, '[^0-9]+', '', 'g')::INT;

    -- Déterminer l'univers et la forme selon les règles
    -- Mundo et Fruity
    IF (ash_num1_int = ash_num2_int) THEN
        -- Déterminer la forme associée à ash_num1
        SELECT forme_associee_id INTO forme1_id FROM Ash WHERE id = ash_num1_int;
        SELECT forme_name INTO forme1_name FROM formes WHERE forme_id = forme1_id;

        -- Vérifier les conditions spécifiques pour fruity
        IF (ash_num1_int = 16 AND room_num1_int IN (9,13) AND room_num2_int IN (9,13)) OR
           (ash_num1_int = 20 AND room_num1_int IN (10,14) AND room_num2_int IN (10,14)) OR
           (ash_num1_int = 24 AND room_num1_int IN (11,15) AND room_num2_int IN (11,15)) OR
           (ash_num1_int = 30 AND room_num1_int IN (12,16) AND room_num2_int IN (12,16)) THEN
            univers := 'fruity';
        ELSE
            univers := 'mundo';
        END IF;

        -- Forme selon ash
        v_forme_id := forme1_name; -- Utiliser l'alias pour éviter l'ambiguïté
        forme_composee := NULL;

    ELSIF (lot_num1_int = lot_num2_int) THEN
        -- Déterminer la forme associée à lot_num1
        CASE lot_num1_int
            WHEN 1 THEN forme1_id := 1;
            WHEN 2 THEN forme1_id := 2;
            WHEN 3 THEN forme1_id := 3;
            WHEN 4 THEN forme1_id := 4;
            ELSE forme1_id := NULL;
        END CASE;

        SELECT forme_name INTO forme1_name FROM formes WHERE forme_id = forme1_id;

        -- Vérifier les conditions spécifiques pour fruity
        IF (lot_num1_int = 1 AND room_num1_int IN (1,2,3,4) AND room_num2_int IN (1,2,3,4)) OR
           (lot_num1_int = 2 AND room_num1_int IN (5,6,7,8) AND room_num2_int IN (5,6,7,8)) OR
           (lot_num1_int = 3 AND room_num1_int IN (9,10,11,12) AND room_num2_int IN (9,10,11,12)) OR
           (lot_num1_int = 4 AND room_num1_int IN (13,14,15,16) AND room_num2_int IN (13,14,15,16)) THEN
            -- Cas déjà couverts par mundo
            NULL;
        ELSE
            univers := 'fruity';
        END IF;

        -- Forme selon lot
        v_forme_id := forme1_name; -- Utiliser l'alias pour éviter l'ambiguïté
    END IF;

    RETURN univers;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_chip_id(univers text, ligne text, colonne text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    row_num INTEGER;
    col_num INTEGER;
    chip_id INTEGER;
BEGIN
    -- Convertir les valeurs de ligne et colonne en nombres
    row_num := SUBSTRING(ligne FROM 2)::INTEGER;
    col_num := SUBSTRING(colonne FROM 2)::INTEGER;

    -- Calculer le chip_id
    chip_id := (row_num - 1) * 6 + col_num;

    -- Retourner le chip_id
    RETURN chip_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_granque_value(granque_name character varying)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    result INTEGER := 0;
BEGIN
    IF granque_name IS NULL OR granque_name = '' THEN
        RETURN 0;
    END IF;

    -- Extraire le nombre après 'Q'
    IF granque_name ~ 'Q(\d+)' THEN
        result := (regexp_replace(granque_name, 'Q(\d+)', '\1'))::INTEGER;
    END IF;

    RETURN result;
EXCEPTION WHEN OTHERS THEN
    RETURN 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.determine_tome(sigma_chip numeric)
 RETURNS character varying
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
