CREATE OR REPLACE FUNCTION public.determiner_univers_forme(lot_num1 text, lot_num2 text, ash_num1 text, ash_num2 text, room_num1 text, room_num2 text, OUT univers text, OUT forme text)
 RETURNS record
 LANGUAGE plpgsql
AS $function$
DECLARE
    form1 TEXT;
    form2 TEXT;
BEGIN
    RAISE NOTICE 'Input values - lot1: %, lot2: %, ash1: %, ash2: %, room1: %, room2: %', 
        lot_num1, lot_num2, ash_num1, ash_num2, room_num1, room_num2;

    -- ==================== MUNDO/FRUITY CONDITIONS ==================== 

    -- Carré (ash16/lot1)
    IF (lot_num1 IN ('col1', 'col2') AND ash_num1 IN ('ash16', 'lot1') AND 
        lot_num2 IN ('col1', 'col2') AND ash_num2 IN ('ash16', 'lot1')) THEN
        IF (ash_num1 = 'lot1' AND ash_num2 = 'lot1') THEN
            IF NOT (room_num1 IN ('room1', 'room2', 'room3', 'room4') AND 
                   room_num2 IN ('room1', 'room2', 'room3', 'room4')) THEN
                univers := 'fruity';
                forme := 'carre';
                RAISE NOTICE 'Condition Fruity Carré (lot1) matched';
            ELSE
                univers := 'mundo';
                forme := 'carre';
                RAISE NOTICE 'Condition Mundo Carré (lot1) matched';
            END IF;
        ELSE
            IF NOT (room_num1 IN ('room9', 'room13') AND room_num2 IN ('room9', 'room13')) THEN
                univers := 'mundo';
                forme := 'carre';
                RAISE NOTICE 'Condition Mundo Carré (ash16) matched';
            ELSE
                univers := 'fruity';
                forme := 'carre';
                RAISE NOTICE 'Condition Fruity Carré (ash16) matched';
            END IF;
        END IF;
        RETURN;
    END IF;

    -- Triangle (ash20/lot2)
    IF (lot_num1 IN ('col1', 'col2') AND ash_num1 IN ('ash20', 'lot2') AND 
        lot_num2 IN ('col1', 'col2') AND ash_num2 IN ('ash20', 'lot2')) THEN
        IF (ash_num1 = 'lot2' AND ash_num2 = 'lot2') THEN
            IF NOT (room_num1 IN ('room5', 'room6', 'room7', 'room8') AND 
                   room_num2 IN ('room5', 'room6', 'room7', 'room8')) THEN
                univers := 'fruity';
                forme := 'triangle';
                RAISE NOTICE 'Condition Fruity Triangle (lot2) matched';
            ELSE
                univers := 'mundo';
                forme := 'triangle';
                RAISE NOTICE 'Condition Mundo Triangle (lot2) matched';
            END IF;
        ELSE
            IF NOT (room_num1 IN ('room10', 'room14') AND room_num2 IN ('room10', 'room14')) THEN
                univers := 'mundo';
                forme := 'triangle';
                RAISE NOTICE 'Condition Mundo Triangle (ash20) matched';
            ELSE
                univers := 'fruity';
                forme := 'triangle';
                RAISE NOTICE 'Condition Fruity Triangle (ash20) matched';
            END IF;
        END IF;
        RETURN;
    END IF;

    -- Cercle (ash24/lot3)
    IF (lot_num1 IN ('col1', 'col2') AND ash_num1 IN ('ash24', 'lot3') AND 
        lot_num2 IN ('col1', 'col2') AND ash_num2 IN ('ash24', 'lot3')) THEN
        IF (ash_num1 = 'lot3' AND ash_num2 = 'lot3') THEN
            univers := 'fruity';
            forme := 'cercle';
            RAISE NOTICE 'Condition Fruity Cercle (lot3) matched';
        ELSE
            IF NOT (room_num1 IN ('room11', 'room15') AND room_num2 IN ('room11', 'room15')) THEN
                univers := 'mundo';
                forme := 'cercle';
                RAISE NOTICE 'Condition Mundo Cercle (ash24) matched';
            ELSE
                univers := 'fruity';
                forme := 'cercle';
                RAISE NOTICE 'Condition Fruity Cercle (ash24) matched';
            END IF;
        END IF;
        RETURN;
    END IF;

    -- Rectangle (ash30/lot4)
    IF (lot_num1 IN ('col1', 'col2') AND ash_num1 IN ('ash30', 'lot4') AND 
        lot_num2 IN ('col1', 'col2') AND ash_num2 IN ('ash30', 'lot4')) THEN
        IF (ash_num1 = 'lot4' AND ash_num2 = 'lot4') THEN
            univers := 'fruity';
            forme := 'rectangle';
            RAISE NOTICE 'Condition Fruity Rectangle (lot4) matched';
        ELSE
            IF NOT (room_num1 IN ('room12', 'room16') AND room_num2 IN ('room12', 'room16')) THEN
                univers := 'mundo';
                forme := 'rectangle';
                RAISE NOTICE 'Condition Mundo Rectangle (ash30) matched';
            ELSE
                univers := 'fruity';
                forme := 'rectangle';
                RAISE NOTICE 'Condition Fruity Rectangle (ash30) matched';
            END IF;
        END IF;
        RETURN;
    END IF;

    -- ==================== TRIGGA CONDITIONS ====================
    IF (lot_num1 IN ('col3', 'col4', 'col5', 'col6') AND 
        lot_num2 IN ('col3', 'col4', 'col5', 'col6')) THEN
        form1 := (SELECT get_form(ash_num1));
        form2 := (SELECT get_form(ash_num2));

        univers := 'trigga';
        IF ash_num1 = ash_num2 THEN
            forme := form1;
        ELSE
            forme := form1 || '-' || form2;
        END IF;
        RAISE NOTICE 'Condition Trigga matched: %', forme;
        RETURN;
    END IF;

    -- ==================== SUNSHINE CONDITIONS ====================
    IF ((lot_num1 IN ('col1', 'col2') AND lot_num2 IN ('col3', 'col4', 'col5', 'col6')) OR
        (lot_num2 IN ('col1', 'col2') AND lot_num1 IN ('col3', 'col4', 'col5', 'col6'))) THEN
        form1 := (SELECT get_form(ash_num1));
        form2 := (SELECT get_form(ash_num2));

        univers := 'sunshine';
        IF ash_num1 = ash_num2 THEN
            forme := form1;
        ELSE
            forme := form1 || '-' || form2;
        END IF;
        RAISE NOTICE 'Condition Sunshine matched: %', forme;
        RETURN;
    END IF;

    -- ==================== ROASTER CONDITIONS ====================
    IF (lot_num1 IN ('col1', 'col2') AND lot_num2 IN ('col1', 'col2') AND 
        ash_num1 != ash_num2 AND lot_num1 != lot_num2) THEN
        form1 := (SELECT get_form(ash_num1));
        form2 := (SELECT get_form(ash_num2));

        univers := 'roaster';
        forme := form1 || '-' || form2;
        RAISE NOTICE 'Condition Roaster matched: %', forme;
        RETURN;
    END IF;

    -- ==================== DEFAULT CASE ====================
    univers := NULL;
    forme := NULL;
    RAISE NOTICE 'Aucune condition ne correspond';
    RETURN;
END;
$function$

