        -- Condition Rectangle (ash30/lot4)
        IF (ash_num1 IN ('ash30', 'lot4') AND ash_num2 IN ('ash30', 'lot4')) THEN
            IF (ash_num1 = 'lot4' AND ash_num2 = 'lot4') THEN
