                    RETURN;
                ELSE
                    univers := 'fruity';
                    forme := 'rectangle';
                    RETURN;
                END IF;
            END IF;
        END IF;
    END IF;

    -- ==================== TRIGGA ====================
    IF (lot_num1 IN ('col3','col4','col5','col6') AND 
       lot_num2 IN ('col3','col4','col5','col6')) THEN

        SELECT public.get_form(ash_num1) INTO v_form1;
        SELECT public.get_form(ash_num2) INTO v_form2;

        univers := 'trigga';
        IF ash_num1 = ash_num2 THEN
            forme := v_form1;
        ELSE
            forme := v_form1 || '-' || v_form2;
