CREATE OR REPLACE FUNCTION public.update_ranking_values()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Mise à jour des références de base
    IF NEW.denomination IS NOT NULL THEN
        -- Extraction du base_name et denomination_row_number
        IF NEW.denomination ~ '^[a-zA-Z]+ [0-9]+$' THEN
            NEW.base_name := SPLIT_PART(NEW.denomination, ' ', 1);
            NEW.denomination_row_number := CAST(SPLIT_PART(NEW.denomination, ' ', 2) AS INTEGER);
        END IF;

        -- Calcul automatique du row_number et alpha_ranking pour les nouveaux éléments
        IF TG_OP = 'INSERT' THEN
            SELECT COALESCE(MAX(row_number), 0) + 1 INTO NEW.row_number
            FROM combinations
            WHERE 
                univers = NEW.univers AND
                forme = NEW.forme AND
                denomination = NEW.denomination;

            NEW.alpha_ranking := CHR(96 + NEW.row_number);
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_alpha_ranking(row_num integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    quotient INT;
    remainder INT;
    result TEXT;
BEGIN
    quotient := (row_num - 1) / 26;
    remainder := (row_num - 1) % 26;

    result := CHR(97 + remainder); -- 'a' à 'z'

    IF quotient > 0 THEN
        result := get_alpha_ranking(quotient) || result;
    END IF;

    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_alpha_code(row_num bigint)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    code TEXT := '';
    num BIGINT := row_num - 1;
BEGIN
    LOOP
        code := CHR(97 + (num % 26)::INTEGER) || code;
        num := num / 26;
        EXIT WHEN num = 0;
    END LOOP;
    RETURN code;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_alpha_ranking(row_num bigint)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    quotient BIGINT;
    remainder BIGINT;
    result TEXT := '';
BEGIN
    -- Convertir le numéro en code alphabétique
    WHILE row_num > 0 LOOP
        quotient := (row_num - 1) / 26;
        remainder := (row_num - 1) % 26;
        result := CHR(97 + remainder::INTEGER) || result; -- Casting explicite en INTEGER
        row_num := quotient;
    END LOOP;

    RETURN result;
END;
$function$

