CREATE OR REPLACE FUNCTION public.calculate_tomes_all_univers_final_v11()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    univers_list TEXT[] := ARRAY['mundo', 'fruity', 'trigga', 'roaster', 'sunshine'];
    current_univers TEXT;
    processed_count INTEGER := 0;
    total_processed INTEGER := 0;
    error_count INTEGER := 0;
    valid_tomes TEXT[];
    default_tome TEXT := 'tome1';
BEGIN
    RAISE NOTICE 'Début du calcul des tomes pour tous les univers...';

    -- Récupérer les valeurs de tome valides
    SELECT array_agg(tome_name) INTO valid_tomes FROM tomes;

    IF valid_tomes IS NULL OR array_length(valid_tomes, 1) = 0 THEN
        -- Créer des valeurs par défaut si la table est vide
        INSERT INTO tomes (tome_name) VALUES 
            ('tome1'),
            ('tome2'), 
            ('tome3')
        ON CONFLICT (tome_name) DO NOTHING;

        SELECT array_agg(tome_name) INTO valid_tomes FROM tomes;
        RAISE NOTICE 'Valeurs de tome créées : %', valid_tomes;
    ELSE
        RAISE NOTICE 'Valeurs de tome valides : %', valid_tomes;
    END IF;

    FOREACH current_univers IN ARRAY univers_list LOOP
        BEGIN
            RAISE NOTICE 'Traitement de l''univers : %', current_univers;

            -- Calculer et mettre à jour les tomes
            UPDATE combinations c
            SET tome = CASE 
                WHEN calc.tome_attributed = ANY(valid_tomes) THEN calc.tome_attributed
                ELSE default_tome -- Utiliser la valeur par défaut
            END
            FROM (
                WITH chip_denominations AS (
                    SELECT 
                        c2.chip,
                        nd.full_name AS denomination,
                        MAX(get_granque_value(c2.granque_name)) AS granque_value,
                        COUNT(DISTINCT c2.combination_id) AS combination_count
                    FROM 
                        combinations c2
                        JOIN numbered_denominations nd ON c2.denomination_id = nd.denomination_id
                    WHERE 
                        c2.univers = current_univers
                        AND c2.denomination_id IS NOT NULL
                    GROUP BY 
                        c2.chip, nd.full_name
                ),
                chip_totals AS (
                    SELECT 
                        chip,
                        SUM(granque_value) AS total_granque,
                        SUM(combination_count) AS total_combinations
                    FROM 
                        chip_denominations
                    GROUP BY 
                        chip
                ),
                chip_final AS (
                    SELECT 
                        chip,
                        determine_tome((total_granque + total_combinations)::NUMERIC) AS tome_attributed
                    FROM 
                        chip_totals
                )
                SELECT 
                    chip,
                    tome_attributed
                FROM 
                    chip_final
            ) calc
            WHERE c.univers = current_univers
            AND c.chip = calc.chip
            AND c.denomination_id IS NOT NULL;

            GET DIAGNOSTICS processed_count = ROW_COUNT;
            total_processed := total_processed + processed_count;
            RAISE NOTICE 'Univers % traité : % lignes mises à jour', current_univers, processed_count;

        EXCEPTION WHEN OTHERS THEN
            error_count := error_count + 1;
            RAISE WARNING 'Erreur lors du traitement de l''univers % : %', current_univers, SQLERRM;
        END;
    END LOOP;

    RAISE NOTICE 'Calcul terminé : % univers traités, % erreurs, % lignes mises à jour', 
                 array_length(univers_list, 1) - error_count, error_count, total_processed;
END;
$function$

CREATE OR REPLACE FUNCTION public.populate_ligne_colonne()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    ligne_value TEXT;
    colonne_value TEXT;
BEGIN
    -- Récupérer les valeurs de ligne et colonne pour le chip spécifié
    SELECT ligne, colonne INTO ligne_value, colonne_value
    FROM chips_relation
    WHERE chip = NEW.chip;

    -- Vérifier si les valeurs de ligne et colonne ont été trouvées
    IF ligne_value IS NOT NULL AND colonne_value IS NOT NULL THEN
        -- Mettre à jour les valeurs de ligne et colonne dans la table combinations
        NEW.ligne = ligne_value;
        NEW.colonne = colonne_value;
    ELSE
        -- Log d'erreur si les valeurs de ligne et colonne n'ont pas été trouvées
        RAISE NOTICE 'No ligne and colonne found for chip % in chips_relation', NEW.chip;
    END IF;

    RETURN NEW;
END;
$function$

