    END LOOP;

    RAISE NOTICE 'Calcul terminé : % univers traités, % erreurs, % lignes mises à jour', 
                 array_length(univers_list, 1) - error_count, error_count, total_processed;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_ligne_colonne()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    ligne_value TEXT;
    colonne_value TEXT;
BEGIN
    -- Récupérer les valeurs de ligne et colonne pour le chip spécifié
    SELECT ligne, colonne INTO ligne_value, colonne_value
    FROM chips_relation
    WHERE chip = NEW.chip;

    -- Vérifier si les valeurs de ligne et colonne ont été trouvées
    IF ligne_value IS NOT NULL AND colonne_value IS NOT NULL THEN
        -- Mettre à jour les valeurs de ligne et colonne dans la table combinations
        NEW.ligne = ligne_value;
        NEW.colonne = colonne_value;
    ELSE
        -- Log d'erreur si les valeurs de ligne et colonne n'ont pas été trouvées
        RAISE NOTICE 'No ligne and colonne found for chip % in chips_relation', NEW.chip;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_denomination_columns()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Mettre à jour base_name si denomination change
    IF NEW.denomination IS NOT NULL AND (OLD.denomination IS NULL OR OLD.denomination != NEW.denomination) THEN
        NEW.base_name := SPLIT_PART(NEW.denomination, ' ', 1);

        -- Mettre à jour denomination_id
        SELECT denomination_id INTO NEW.denomination_id
        FROM numbered_denominations
        WHERE full_name = NEW.denomination;

        -- Si la dénomination numérotée n'existe pas, la créer
        IF NEW.denomination_id IS NULL THEN
            -- Vérifier si la deuxième partie de la chaîne est un nombre
            IF SPLIT_PART(NEW.denomination, ' ', 2) ~ '^[0-9]+$' THEN
                INSERT INTO numbered_denominations (base_name, index_number)
                VALUES (
                    SPLIT_PART(NEW.denomination, ' ', 1),
                    SPLIT_PART(NEW.denomination, ' ', 2)::integer
                )
                ON CONFLICT (base_name, index_number) DO NOTHING;

                SELECT denomination_id INTO NEW.denomination_id
                FROM numbered_denominations
                WHERE full_name = NEW.denomination;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
